/**
 * True sliding-window rate limiter for Express.
 *
 * Unlike a fixed-window limiter (which resets a counter every N ms and lets a
 * client burst 2x the limit across a boundary), this stores the timestamp of
 * every request and, on each new request, evicts timestamps older than
 * `windowMs` before counting. The window therefore slides continuously with
 * "now" — there is no periodic reset.
 *
 * NOTE ON `req.ip` AND PROXIES:
 * By default Express sets `req.ip` from the socket's remote address. If your
 * app runs behind a reverse proxy / load balancer (Nginx, Cloudflare, ELB,
 * Heroku, ...), every request will appear to come from the proxy's IP and all
 * clients will share a single bucket. Enable trust proxy so Express derives
 * `req.ip` from `X-Forwarded-For`:
 *
 *     app.set('trust proxy', 1);            // 1 hop: your own nginx
 *     app.set('trust proxy', 'loopback');   // or a specific subnet/list
 *
 * Only trust proxies you actually control — `X-Forwarded-For` is client
 * -spoofable, so a wide-open `app.set('trust proxy', true)` lets attackers
 * forge an IP per request and bypass the limiter entirely. If you terminate at
 * a CDN, prefer that CDN's verified header (e.g. `CF-Connecting-IP`) via the
 * `keyGenerator` option.
 */

const DEFAULT_WINDOW_MS = 60 * 1000;
const DEFAULT_MAX_REQUESTS = 100;
const DEFAULT_CLEANUP_INTERVAL_MS = 60 * 1000;

function createRateLimiter(options = {}) {
  const {
    windowMs = DEFAULT_WINDOW_MS,
    maxRequests = DEFAULT_MAX_REQUESTS,
    cleanupIntervalMs = DEFAULT_CLEANUP_INTERVAL_MS,
    message = 'Rate limit exceeded',
    // Override to key on something other than the client IP (API key, user id,
    // a CDN-verified IP header, ...). Must return a string.
    keyGenerator = (req) => req.ip || req.socket?.remoteAddress || 'unknown',
    // Return true to bypass the limiter for a request (health checks, etc).
    skip = () => false,
  } = options;

  if (!Number.isFinite(windowMs) || windowMs <= 0) {
    throw new TypeError('windowMs must be a positive number');
  }
  if (!Number.isInteger(maxRequests) || maxRequests < 0) {
    throw new TypeError('maxRequests must be a non-negative integer');
  }

  /** @type {Map<string, number[]>} key -> ascending list of request timestamps */
  const hits = new Map();

  /**
   * Drop every timestamp at or before `cutoff`. The array is kept sorted
   * ascending (we only ever append `Date.now()`), so expired entries are always
   * a prefix and a single splice is enough.
   */
  function evictExpired(timestamps, cutoff) {
    let expired = 0;
    while (expired < timestamps.length && timestamps[expired] <= cutoff) {
      expired += 1;
    }
    if (expired > 0) timestamps.splice(0, expired);
    return timestamps;
  }

  function middleware(req, res, next) {
    if (skip(req, res)) return next();

    const now = Date.now();
    const cutoff = now - windowMs;
    const key = String(keyGenerator(req, res) ?? 'unknown');

    let timestamps = hits.get(key);
    if (timestamps === undefined) {
      timestamps = [];
      hits.set(key, timestamps);
    }
    evictExpired(timestamps, cutoff);

    // ---- over the limit -----------------------------------------------
    if (timestamps.length >= maxRequests) {
      // Capacity frees up when the oldest surviving request leaves the window.
      const oldest = timestamps.length > 0 ? timestamps[0] : now;
      const resetAtMs = oldest + windowMs;
      const retryAfter = Math.max(1, Math.ceil((resetAtMs - now) / 1000));

      res.setHeader('X-RateLimit-Limit', String(maxRequests));
      res.setHeader('X-RateLimit-Remaining', '0');
      res.setHeader('X-RateLimit-Reset', String(Math.ceil(resetAtMs / 1000)));
      res.setHeader('Retry-After', String(retryAfter));

      // Deliberately no next(): the chain stops here.
      res.status(429).json({ error: message, retryAfter });
      return;
    }

    // ---- under the limit ----------------------------------------------
    timestamps.push(now);

    const resetAtMs = timestamps[0] + windowMs;
    res.setHeader('X-RateLimit-Limit', String(maxRequests));
    res.setHeader('X-RateLimit-Remaining', String(maxRequests - timestamps.length));
    res.setHeader('X-RateLimit-Reset', String(Math.ceil(resetAtMs / 1000)));

    next();
  }

  // ---- memory management ------------------------------------------------
  // Without this, one Map entry leaks per IP that ever hit the service. The
  // sweep evicts expired timestamps and deletes keys that went fully idle for
  // a full window.
  const cleanupTimer = setInterval(() => {
    const cutoff = Date.now() - windowMs;
    for (const [key, timestamps] of hits) {
      evictExpired(timestamps, cutoff);
      if (timestamps.length === 0) hits.delete(key);
    }
  }, cleanupIntervalMs);

  // Don't hold the event loop open just for the sweep (no-op in browsers/edge).
  if (typeof cleanupTimer.unref === 'function') cleanupTimer.unref();

  // Attached to the middleware itself so `app.use(limiter)` still works while
  // tests / graceful shutdown can call `limiter.close()`.
  middleware.close = function close() {
    clearInterval(cleanupTimer);
    hits.clear();
  };
  middleware.resetKey = (key) => hits.delete(String(key));
  middleware.resetAll = () => hits.clear();
  // Live count for a key, expired entries excluded.
  middleware.count = (key) => {
    const timestamps = hits.get(String(key));
    if (!timestamps) return 0;
    return evictExpired(timestamps, Date.now() - windowMs).length;
  };

  return middleware;
}

