```js
// rateLimiter.js
'use strict';

/**
 * Creates a true sliding-window rate limiting middleware.
 *
 * Unlike a fixed window (which resets counts at fixed clock boundaries and
 * allows bursts of up to 2x maxRequests around the boundary), this
 * implementation keeps a per-IP log of request timestamps and, on every
 * request, discards timestamps older than `windowMs` before counting. The
 * window is always relative to "now", so it slides continuously.
 *
 * @param {Object} [options]
 * @param {number} [options.windowMs=60000] Window size in milliseconds.
 * @param {number} [options.maxRequests=100] Max requests allowed per window.
 * @returns {Function} Express middleware, with an attached `close()` method
 *   that clears the internal cleanup timer.
 */
function createRateLimiter(options = {}) {
  const windowMs = options.windowMs ?? 60000;
  const maxRequests = options.maxRequests ?? 100;

  if (windowMs <= 0) throw new TypeError('windowMs must be > 0');
  if (maxRequests < 0) throw new TypeError('maxRequests must be >= 0');

  // ip -> array of request timestamps (ms epoch), kept in ascending order.
  const clients = new Map();

  /**
   * Drops timestamps older than the window, given the array is sorted
   * ascending (it always is, since we only ever push `Date.now()`, which
   * is monotonically non-decreasing).
   */
  function pruneOld(timestamps, now) {
    const cutoff = now - windowMs;
    let i = 0;
    while (i < timestamps.length && timestamps[i] <= cutoff) i++;
    return i === 0 ? timestamps : timestamps.slice(i);
  }

  // Periodic sweep: forget IPs that have been completely idle for a full
  // window, so the Map doesn't grow forever with stale/one-off clients.
  const cleanupTimer = setInterval(() => {
    const now = Date.now();
    const cutoff = now - windowMs;
    for (const [ip, timestamps] of clients) {
      const last = timestamps[timestamps.length - 1];
      if (last === undefined || last <= cutoff) {
        clients.delete(ip);
      }
    }
  }, 60000);

  // Don't let the cleanup timer keep the Node process alive on its own
  // (still call close() explicitly on graceful shutdown — see below).
  if (typeof cleanupTimer.unref === 'function') cleanupTimer.unref();

  function rateLimiter(req, res, next) {
    // NOTE on req.ip: Express derives req.ip from the socket address unless
    // `app.set('trust proxy', ...)` is configured, in which case it honors
    // X-Forwarded-For. If this app sits behind Nginx/a load balancer and
    // `trust proxy` isn't set, every request will appear to come from the
    // proxy's IP and share a single rate-limit bucket. Set `trust proxy`
    // appropriately (e.g. `app.set('trust proxy', 1)` for a single
    // reverse proxy hop) so req.ip reflects the real client. Conversely,
    // never blindly trust X-Forwarded-For from untrusted clients — only
    // enable `trust proxy` when you control the proxy in front of you.
    const ip = req.ip;
    const now = Date.now();

    let timestamps = clients.get(ip);
    timestamps = timestamps ? pruneOld(timestamps, now) : [];

    if (timestamps.length >= maxRequests) {
      // Persist the pruned (but not incremented) array so a client that's
      // stopped sending requests doesn't stay "full" forever.
      clients.set(ip, timestamps);

      const oldest = timestamps[0] ?? now;
      const retryAfterSec = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));

      res.setHeader('Retry-After', retryAfterSec);
      res.setHeader('X-RateLimit-Limit', maxRequests);
      res.setHeader('X-RateLimit-Remaining', 0);
      res.setHeader('X-RateLimit-Reset', Math.ceil((oldest + windowMs) / 1000));

      return res.status(429).json({
        error: 'Rate limit exceeded',
        retryAfter: retryAfterSec,
      });
    }

    timestamps.push(now);
    clients.set(ip, timestamps);

    const remaining = maxRequests - timestamps.length;
    // Reset = when the oldest request currently counted will fall out of
    // the window (i.e. when `remaining` would next increase).
    const resetEpochSec = Math.ceil((timestamps[0] + windowMs) / 1000);

    res.setHeader('X-RateLimit-Limit', maxRequests);
    res.setHeader('X-RateLimit-Remaining', remaining);
    res.setHeader('X-RateLimit-Reset', resetEpochSec);

    next();
  }

  /** Stops the background cleanup interval (call on app shutdown / tests). */
  rateLimiter.close = function close() {
    clearInterval(cleanupTimer);
  };

  return rateLimiter;
}

module.exports = { createRateLimiter };
```

### Usage example

```js
// app.js
const express = require('express');
const { createRateLimiter } = require('./rateLimiter');

const app = express();

// If you're behind Nginx/a load balancer (as in this project's deployment
// setup), enable trust proxy so req.ip reflects the real client IP instead
// of the proxy's. `1` = trust the first hop (typical single-reverse-proxy
// setup); adjust the number/CIDR list to match your actual proxy topology.
app.set('trust proxy', 1);

const limiter = createRateLimiter({ windowMs: 60000, maxRequests: 100 });

app.use(limiter); // apply globally
// or scope it: app.use('/api/', limiter);

app.get('/', (req, res) => res.send('ok'));

const server = app.listen(3002);

